import { readFileSync, writeFileSync } from 'node:fs';
import { createHash } from 'node:crypto';
import { gameIconArtwork } from '../src/lib/game-control/icon-artwork.js';
const versions = Object.fromEntries(Object.entries(gameIconArtwork).map(([engine, path]) => [engine,
  createHash('sha256').update(readFileSync(new URL(`../public${path}`, import.meta.url))).digest('hex')]));
writeFileSync(new URL('../src/lib/game-control/icon-versions.js', import.meta.url),
  '// Generated by scripts/generate-game-icon-versions.mjs.\nexport const gameIconVersions = '+JSON.stringify(versions, null, 2)+';\n');
